// Generates src/contexts/reporting/chart-presets-data.ts from the stock themes that ship inside the `echarts` package (Apache-2.0).
// Run: node packages/domain/scripts/build-chart-presets.mjs   Never edit the generated file by hand.
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const pkg = path.dirname(require.resolve("echarts/package.json", { paths: [path.resolve(import.meta.dirname, "../../../apps/web")] }));
const version = JSON.parse(fs.readFileSync(path.join(pkg, "package.json"), "utf8")).version;
const dir = path.join(pkg, "theme");

const hex = (c) => {
  if (typeof c !== "string") return null;
  const m = c.trim().toLowerCase();
  if (/^#[0-9a-f]{6}$/.test(m)) return m;
  if (/^#[0-9a-f]{3}$/.test(m)) return `#${m[1]}${m[1]}${m[2]}${m[2]}${m[3]}${m[3]}`;
  return null;
};
const title = (id) => id.split("-").map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
const out = [];
for (const file of fs.readdirSync(dir).filter((f) => f.endsWith(".js")).sort()) {
  const id = file.replace(/\.js$/, "");
  let captured = null;
  const echarts = { registerTheme: (name, theme) => { captured = theme; } };
  const exports = {};
  new Function("require", "exports", "define", fs.readFileSync(path.join(dir, file), "utf8")).call({}, () => echarts, exports, undefined);
  if (!captured) { console.error(`skipped ${id}: no theme registered`); continue; }
  const colors = (Array.isArray(captured.color) ? captured.color : []).map(hex).filter(Boolean);
  if (colors.length < 4) { console.error(`skipped ${id}: fewer than 4 hex colours`); continue; }
  const bg = hex(captured.backgroundColor);
  const line = captured.line ?? {};
  const width = line.lineStyle?.width ?? line.lineStyle?.normal?.width ?? line.itemStyle?.normal?.lineStyle?.width;
  const smooth = line.smooth;
  out.push({ id, label: title(id), colors, ...(bg ? { background: bg } : {}), ...(typeof width === "number" && width >= 1 && width <= 12 ? { lineWidth: width } : {}), ...(typeof smooth === "boolean" ? { smooth } : {}) });
}
const body = `// GENERATED by packages/domain/scripts/build-chart-presets.mjs from echarts@${version}/theme (Apache-2.0, © The Apache Software Foundation). Do not edit by hand.
export interface EChartsThemeData { id: string; label: string; colors: string[]; background?: string; lineWidth?: number; smooth?: boolean }
export const ECHARTS_THEME_SOURCE = { package: "echarts", version: "${version}", licence: "Apache-2.0" } as const;
export const ECHARTS_THEMES: ReadonlyArray<EChartsThemeData> = ${JSON.stringify(out, null, 2)};
`;
fs.writeFileSync(path.resolve(import.meta.dirname, "../src/contexts/reporting/chart-presets-data.ts"), body);
console.log(`wrote ${out.length} themes from echarts@${version}`);
